import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

interface Titles {
    Optional<String> findById(String id);
}

class TitleService {
    private final Titles titles;
    TitleService(Titles titles) { this.titles = titles; }

    String title(String id) {
        return titles.findById(id)
            .orElseThrow(() -> new IllegalArgumentException("Missing entry"));
    }
}

@ExtendWith(MockitoExtension.class)
class TitleServiceTest {
    @Mock Titles titles;
    @InjectMocks TitleService service;

    @Test
    void returnsStoredTitle() {
        when(titles.findById("entry-1"))
            .thenReturn(Optional.of("Morning"));
        assertEquals("Morning", service.title("entry-1"));
        verify(titles).findById("entry-1");
    }

    @Test
    void reportsMissingEntry() {
        when(titles.findById("missing")).thenReturn(Optional.empty());
        assertThrows(IllegalArgumentException.class,
            () -> service.title("missing"));
    }
}
